<?php
$pageTitle = 'Import History - SGRC';
require_once __DIR__ . '/../../includes/header.php';
require_once __DIR__ . '/../../includes/auth.php';
requireAuth();

$db = Database::getInstance();
$page = max(1, intval($_GET['page'] ?? 1));
$perPage = 20;
$offset = ($page - 1) * $perPage;

$history = $db->query("SELECT h.*, u.username FROM import_history h LEFT JOIN users u ON h.imported_by = u.id ORDER BY h.imported_at DESC LIMIT " . (int)$perPage . " OFFSET " . (int)$offset)->fetchAll();
$total = $db->query("SELECT COUNT(*) as c FROM import_history")->fetch()['c'];
$totalPages = ceil($total / $perPage);
?>

<div class="container-fluid">
    <h2>Import History</h2>
        
            <div class="card">
                    <div class="card-body">
                                <table class="table table-striped">
