                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td class="text-danger"><?php echo $h['records_failed']; ?></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td><?php echo htmlspecialchars($h['username'] ?? '-'); ?></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td><?php echo $h['imported_at']; ?></td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
